SELECT  
LEFT JOIN TB_SY_CODE c ON c.CODE_GRP_ID='IMPR' AND c.CODE=i.IMPR_CD


    i.ISSUE_STAT_CD=#{filter.statusCode}
    1=1
    i.ISSUE_STAT_CD IN ('OPEN','ACT')


    AND p.PROJ_STAT_CD NOT IN ('END','LOSE') AND p.CTRT_END_DT >= #{today}


    AND i.DDLN_DT < #{today} AND i.ISSUE_STAT_CD!='CLOSE'

  AND i.IMPR_CD=#{filter.importanceCode}
  AND i.PROJ_ID=#{filter.projectId}

ORDER BY CASE WHEN i.ISSUE_STAT_CD='CLOSE' THEN 1 ELSE 0 END,
  c.SORT_ORD NULLS LAST, i.DDLN_DT, i.ISSUE_ID

