UPDATE TB_PJ_ISSUE SET ISSUE_TTL=#{input.title},IMPR_CD=#{input.importanceCode},
  DDLN_DT=#{input.dueDate},ISSUE_STAT_CD=#{input.statusCode},ACTN_CN=#{input.actionText},
  MOD_USER_ID=#{actor},MOD_DTTM=clock_timestamp()
WHERE ISSUE_ID=#{issueId} AND PROJ_ID=#{input.projectId}
  AND COALESCE(MOD_DTTM,REG_DTTM) IS NOT DISTINCT FROM #{input.modifiedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
